import{_ as i,l as n,o as e,c as s,v as t,p as l,x as o,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"关税与最优关税","description":"","frontmatter":{"title":"关税与最优关税","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/tariffs-optimal.md","filePath":"econ/tariffs-optimal.md","lastUpdated":1789023840000}'),h={name:"econ/tariffs-optimal.md"};function c(m,a,B,A,_,f){const r=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="关税与最优关税" tabindex="-1">关税与最优关税 <a class="header-anchor" href="#关税与最优关税" aria-label="Permalink to &quot;关税与最优关税&quot;">​</a></h1><div class="epigraph"><p>小国关税把楔子打进国内价格与世界价格，无条款改善，净损失；大国能压低进口世界价格，最优关税为正——直到报复把双方锁进囚徒困境。</p><footer>—— 据 Johnson 最优关税传统；Broda, Limão and Weinstein, AER 2008 对进口弹性与市场势力</footer></div><p><a href="/econ/eaton-kortum">上一课</a>把贸易成本 \\(\\tau\\) 写进份额。本课把 \\(\\tau\\) 的政策部分拆成关税。贸易协定下一课解释为何国家愿意捆住自己的最优关税。本课钉小国损失、大国条款、报复。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>从价关税 \\(t\\) 使国内进口价 \\(=p^w(1+t)\\)。小国：\\(p^w\\) 给定，关税收入是国内转移，消费与生产扭曲造成无谓损失，与<a href="/econ/deadweight-loss">无谓损失</a>同构。大国：进口下降压低 \\(p^w\\)，条款改善部分抵消扭曲，存在最优 \\(t^*\\approx 1/\\varepsilon^*\\)（外国出口供给弹性）。缺口不是再画供给需求，而是：单边最优关税是以邻为壑；对方同样做，双方条款改善对消，扭曲留下。这是协定课的动机。</p><p><span class="marginnote">配额在完全竞争下可关税等价，租金归谁（许可证持有人 vs 政府）改分配。不完全竞争下等价破裂（Krugman / Brander–Spencer 另账）。本课完全竞争为最小。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>局部：进口需求弹性、出口供给弹性。一般均衡：EK / CES 里关税改变 \\(\\pi_{ij}\\) 与工资，福利分解为效率与条款（Costinot–Rodríguez-Clare 一类）。计量：用进口需求弹性估市场势力（Broda–Limão–Weinstein），看实际关税是否向最优靠。这是结构弹性，不是 China shock 的 ATT。</p>',8)),(e(),l(E,null,{default:o(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SM%5B%22%E5%B0%8F%E5%9B%BD%22%5D%20--%3E%20DWL%5B%22%E7%BA%AF%E6%89%AD%E6%9B%B2%2C%20t*%3D0%22%5D%0A%20%20LG%5B%22%E5%A4%A7%E5%9B%BD%22%5D%20--%3E%20TOT%5B%22%E5%8E%8B%E4%BD%8E%20p%5Ew%22%5D%0A%20%20TOT%20--%3E%20POS%5B%22t*%20%3E%200%22%5D%0A%20%20RET%5B%22%E6%8A%A5%E5%A4%8D%22%5D%20--%3E%20PD%5B%22%E5%9B%9A%E5%BE%92%E5%9B%B0%E5%A2%83%22%5D%0A%20%20PD%20--%3E%20GATT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%8D%8F%E5%AE%9A%E7%BA%A6%E6%9D%9F%20t%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与李嘉图：关税把分工从机会成本推开，浪费比较利益。与 SS：保护提高进口竞争行业密集要素的报酬，这是分配，不是小国效率最优。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是楔子加条款。小国没有条款通道，关税是向自己征税再补贴生产者。大国有买方势力，关税是抽取外国租金。抽取能成功是因为外国供给向上倾斜。世界作为整体，关税仍是负和（扭曲），再分配从外国生产者到本国国库与生产者。</p><p>运输成本、非关税壁垒（标准、红头）可以有类似楔子，但福利核算更脏（有的标准含共同收益）。本课关税是干净楔子。</p><p><span class="marginnote"> Lerner 对称：进口税与出口税在某些条件下等价。政策语言里「只保护进口」仍会伤出口部门——一般均衡的相对价格。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某一国的关税表写成已经最优。战略性贸易（补贴本国寡头）是不完全竞争另课，不并入最优关税公式。下一课 GATT/WTO：互惠与最惠国把 \\(t^*\\) 换成可执行的约束。全球价值链让名义关税与有效保护率分叉，后课再写。不要用最优关税为所有保护背书——那是单边、给定对方不报复的公式。</p><p>后课默认：小国自由贸易效率最优；大国单边 \\(t^*\\gt 0\\) 是条款抽取；报复使双方变差。协定用互惠解开困境。SS 解释谁支持保护，不解释小国效率。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>小国关税：扭曲，无条款，最优为零。</li><li>大国：买方势力给出 \\(t^*\\approx 1/\\varepsilon^*\\)。</li><li>报复把条款对消，留下无谓损失。</li><li>保护的分配（SS）与效率（本课）要分开写。</li><li>出处：Johnson 最优关税；Broda, Limão and Weinstein, <em>AER</em> 2008；Lerner 对称。</li></ul>',10))])}const D=i(h,[["render",c]]);export{T as __pageData,D as default};
